using System;using System.Collections.Generic;public class Solution{public int ShortestDistance(int[][]g){int m=g.Length,n=g[0].Length,bc=0;int[][]sum=new int[m][],reach=new int[m][];for(int i=0;i<m;i++){sum[i]=new int[n];reach[i]=new int[n];}int[][]d={new[]{1,0},new[]{-1,0},new[]{0,1},new[]{0,-1}};for(int i=0;i<m;i++)for(int j=0;j<n;j++)if(g[i][j]==1){bc++;var q=new Queue<(int,int)>();q.Enqueue((i,j));bool[][]v=new bool[m][];for(int r=0;r<m;r++)v[r]=new bool[n];int dist=0;while(q.Count>0){int z=q.Count;dist++;while(z-->0){var(p,qc)=q.Dequeue();foreach(var x in d){int a=p+x[0],b=qc+x[1];if(a>=0&&b>=0&&a<m&&b<n&&!v[a][b]&&g[a][b]==0){v[a][b]=true;sum[a][b]+=dist;reach[a][b]++;q.Enqueue((a,b));}}}}}int ans=int.MaxValue;for(int i=0;i<m;i++)for(int j=0;j<n;j++)if(g[i][j]==0&&reach[i][j]==bc)ans=Math.Min(ans,sum[i][j]);return ans==int.MaxValue?-1:ans;}}
